from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        count = {}
        n = len(nums)

        # Iterate through all subarrays of size k
        for i in range(n - k + 1):
            subarray = nums[i : i + k]
            # Use a set to track unique numbers in the current subarray
            # This ensures we count the subarray occurrence, not the element frequency within the subarray
            for num in set(subarray):
                count[num] = count.get(num, 0) + 1

        result = -1
        # Find the largest number that appears in exactly one subarray
        for num, freq in count.items():
            if freq == 1:
                if num > result:
                    result = num

        return result
