class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)

        for i in range(n):
            is_good = True

            # Check if i-k exists
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check if i+k exists
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total += nums[i]

        return total
