import sys

def main():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
    except StopIteration:
        return

    P = []
    for _ in range(N):
        try:
            val = int(next(iterator))
            P.append(val)
        except StopIteration:
            break

    # ranks[i] stores the rank of person i (0-indexed in list)
    # 0 means rank is not yet determined
    ranks = [0] * N
    r = 1

    while True:
        # Find the maximum score among undetermined people
        max_score = -1
        for i in range(N):
            if ranks[i] == 0:
                if P[i] > max_score:
                    max_score = P[i]

        # If no undetermined people remain, break
        if max_score == -1:
            break

        # Count how many undetermined people have this max_score
        k = 0
        for i in range(N):
            if ranks[i] == 0 and P[i] == max_score:
                k += 1

        # Assign rank r to these k people
        for i in range(N):
            if ranks[i] == 0 and P[i] == max_score:
                ranks[i] = r

        # Update r
        r += k

    # Print the ranks
    for rank in ranks:
        print(rank)

