        total_sum = 0
        n = len(nums)

        for i in range(n):
            is_good = True

            # Check if strictly greater than element at i - k (if it exists)
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check if strictly greater than element at i + k (if it exists)
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total_sum += nums[i]

        return total_sum
