import sys

def main():
    # Read all input from standard input
    # split() handles newlines and spaces automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Read Grid S (N rows)
    S = []
    for _ in range(N):
        S.append(next(iterator))

    # Read Grid T (M rows)
    T = []
    for _ in range(M):
        T.append(next(iterator))

    # Iterate through all possible top-left positions (a, b) in S
    # a corresponds to the 1-based row index
    # b corresponds to the 1-based column index
    # In 0-based indexing for Python lists:
    # row i ranges from 0 to N - M
    # col j ranges from 0 to N - M

    for i in range(N - M + 1):
        for j in range(N - M + 1):
            match = True
            # Check if the MxM subgrid starting at (i, j) in S matches T
            for r in range(M):
                for c in range(M):
                    if S[i + r][j + c] != T[r][c]:
                        match = False
                        break
                if not match:
                    break

            if match:
                # Found the match, print 1-based coordinates and exit
                print(f"{i + 1} {j + 1}")
                return

if __name__ == '__main__':
    main()
