from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Convert each property list to a set to handle distinct integers efficiently
        sets = [set(p) for p in properties]

        # Initialize Union-Find (Disjoint Set Union) structure
        parent = list(range(n))

        # Find function with path compression
        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        # Union function to merge two sets
        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        # Iterate over all unique pairs (i, j) with i < j
        for i in range(n):
            for j in range(i + 1, n):
                # Calculate the number of distinct integers common to both
                intersection_size = len(sets[i] & sets[j])

                # If the intersection size is at least k, add an edge between i and j
                if intersection_size >= k:
                    union(i, j)

        # The number of connected components is the number of unique roots
        return len(set(find(i) for i in range(n)))
